import std.io
import std.time

test "timeout virtual" {
    scope {
        let adv = task effect time {
            advanceTime(100)
        }
        let r = scope timeout(50) {
            let t = task effect time {
                let _ = time.sleep(1000)
            }
            let _ = t.await()
        }
        match r {
            Ok(_) => { io.println("ok") }
            Err(_) => { io.println("timedout") }
        }
        let _ = adv.await()
    }
    assert(true, "done")
}
